// Get or refresh Facebook access token
const appId = 'YOUR_FACEBOOK_APP_ID';
const appSecret = 'YOUR_FACEBOOK_APP_SECRET';
const existingToken = 'YOUR_EXISTING_ACCESS_TOKEN'; // Long-lived user access token

// For production, you should store tokens securely and implement proper refresh logic
// This is a simplified example

return [{
  json: {
    access_token: existingToken,
    app_id: appId,
    app_secret: appSecret
  }
}];

// Process Instagram posts from Graph API response
const response = $input.first().json;
const competitor = $input.first().json;
const lastCheckDate = competitor.last_check || new Date(Date.now() - 24*60*60*1000).toISOString();

let newPosts = [];

if (response.body && response.body.data) {
  const posts = response.body.data;

  for (const post of posts) {
    const postDate = new Date(post.timestamp);
    const checkDate = new Date(lastCheckDate);

    if (postDate > checkDate) {
      newPosts.push({
        username: competitor.username,
        platform: 'instagram',
        post_id: post.id,
        content: post.caption || 'No caption',
        url: post.permalink,
        date: post.timestamp,
        image: post.media_url,
        media_type: post.media_type,
        company_name: competitor.company_name
      });
    }
  }
}

return newPosts.map(post => ({ json: post }));

// Process Facebook posts from Graph API response
const response = $input.first().json;
const competitor = $input.first().json;
const lastCheckDate = competitor.last_check || new Date(Date.now() - 24*60*60*1000).toISOString();

let newPosts = [];

if (response.body && response.body.data) {
  const posts = response.body.data;

  for (const post of posts) {
    const postDate = new Date(post.created_time);
    const checkDate = new Date(lastCheckDate);

    if (postDate > checkDate) {
      const content = post.message || post.story || 'No content available';
      const image = post.full_picture || (post.attachments && post.attachments.data[0] && post.attachments.data[0].media && post.attachments.data[0].media.image && post.attachments.data[0].media.image.src);

      newPosts.push({
        username: competitor.username,
        platform: 'facebook',
        post_id: post.id,
        content: content,
        url: post.permalink_url,
        date: post.created_time,
        image: image,
        company_name: competitor.company_name
      });
    }
  }
}

return newPosts.map(post => ({ json: post }));

// Format email content for new posts
const posts = $input.all();

if (posts.length === 0) {
  return [{ json: { skip: true } }];
}

let emailContent = `
<h2>🔔 Новые публикации конкурентов</h2>
<p>Обнаружены новые публикации за последние 24 часа через Graph API:</p>
`;

let platformCounts = {};

for (const item of posts) {
  const post = item.json;

  if (!platformCounts[post.platform]) {
    platformCounts[post.platform] = 0;
  }
  platformCounts[post.platform]++;

  const platformIcon = post.platform === 'instagram' ? '📸' : '📘';
  const mediaInfo = post.media_type ? ` (${post.media_type})` : '';

  emailContent += `
  <div style="border: 1px solid #ddd; padding: 15px; margin: 10px 0; border-radius: 8px; background: #fafafa;">
    <h3>${platformIcon} ${post.platform.toUpperCase()}: ${post.company_name} (@${post.username})</h3>
    <p><strong>🕐 Дата:</strong> ${new Date(post.date).toLocaleString('ru-RU')}</p>
    <p><strong>🆔 Post ID:</strong> ${post.post_id}</p>
    ${mediaInfo ? `<p><strong>📁 Тип медиа:</strong> ${post.media_type}</p>` : ''}
    <p><strong>📝 Содержание:</strong></p>
    <blockquote style="background: #fff; padding: 12px; border-left: 4px solid #007cba; margin: 10px 0; border-radius: 4px;">
      ${post.content.substring(0, 800)}${post.content.length > 800 ? '...' : ''}
    </blockquote>
    <p><a href="${post.url}" target="_blank" style="color: #007cba; text-decoration: none; font-weight: bold;">🔗 Посмотреть публикацию</a></p>
    ${post.image ? `<p><img src="${post.image}" style="max-width: 100%; height: auto; max-height: 400px; border-radius: 4px; box-shadow: 0 2px 8px rgba(0,0,0,0.1);" alt="Post media"></p>` : ''}
  </div>
  `;
}

// Add summary
const summary = Object.entries(platformCounts)
  .map(([platform, count]) => `${platform}: ${count}`)
  .join(', ');

emailContent += `
<hr style="margin: 20px 0; border: none; border-top: 1px solid #ddd;">
<div style="background: #f0f8ff; padding: 15px; border-radius: 8px; margin: 15px 0;">
  <h4>📊 Сводка:</h4>
  <p><strong>Всего новых публикаций:</strong> ${posts.length}</p>
  <p><strong>По платформам:</strong> ${summary}</p>
</div>
<p><small style="color: #666;">🤖 Автоматическое уведомление от системы мониторинга конкурентов (Graph API)</small></p>
`;

return [{
  json: {
    subject: `🔔 Обнаружено ${posts.length} новых публикаций конкурентов (${summary})`,
    html: emailContent,
    text: posts.map(item => `${item.json.platform.toUpperCase()}: ${item.json.company_name} (@${item.json.username}) - ${item.json.content.substring(0, 200)}...`).join('\n\n')
  }
}];

// Handle API errors and rate limiting
const input = $input.first().json;

if (input.statusCode >= 400) {
  console.log(`API Error: ${input.statusCode} - ${input.body?.error?.message || 'Unknown error'}`);

  if (input.statusCode === 429) {
    // Rate limit exceeded
    return [{ 
      json: { 
        error: 'Rate limit exceeded', 
        retry_after: input.headers?.['retry-after'] || 3600,
        skip: true
      } 
    }];
  }

  if (input.statusCode === 190 || input.statusCode === 401) {
    // Token expired or invalid
    return [{ 
      json: { 
        error: 'Access token expired or invalid', 
        skip: true
      } 
    }];
  }

  return [{ 
    json: { 
      error: `HTTP ${input.statusCode}: ${input.body?.error?.message || 'Unknown error'}`,
      skip: true
    } 
  }];
}

return [$input.first()];
